use std::net::{Ipv4Addr, Ipv6Addr};
use std::path::Path;
use std::process::Command;
use thiserror::Error;

/// RFC 7807 Problem Details error
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize, utoipa::ToSchema)]
pub struct ProblemDetails {
    /// A URI reference that identifies the problem type
    #[serde(skip_serializing_if = "Option::is_none")]
    pub type_uri: Option<String>,
    /// A short, human-readable summary of the problem type
    pub title: String,
    /// The HTTP status code generated by the origin server
    pub status: u16,
    /// A human-readable explanation specific to this occurrence
    #[serde(skip_serializing_if = "Option::is_none")]
    pub detail: Option<String>,
    /// A URI reference that identifies the specific occurrence of the problem
    #[serde(skip_serializing_if = "Option::is_none")]
    pub instance: Option<String>,
    /// Additional problem-specific fields
    #[serde(flatten)]
    pub extensions: std::collections::HashMap<String, serde_json::Value>,
}

impl ProblemDetails {
    pub fn new(status: u16, title: &str) -> Self {
        Self {
            type_uri: None,
            title: title.to_string(),
            status,
            detail: None,
            instance: None,
            extensions: std::collections::HashMap::new(),
        }
    }

    pub fn with_detail(mut self, detail: &str) -> Self {
        self.detail = Some(detail.to_string());
        self
    }

    pub fn with_instance(mut self, instance: &str) -> Self {
        self.instance = Some(instance.to_string());
        self
    }

    pub fn with_type(mut self, type_uri: &str) -> Self {
        self.type_uri = Some(type_uri.to_string());
        self
    }

    pub fn with_extension(mut self, key: &str, value: serde_json::Value) -> Self {
        self.extensions.insert(key.to_string(), value);
        self
    }

    pub fn with_extensions(
        mut self,
        ext: std::collections::HashMap<String, serde_json::Value>,
    ) -> Self {
        self.extensions = ext;
        self
    }
}

/// Validation error codes for precise error identification
#[derive(
    Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize, utoipa::ToSchema,
)]
#[serde(rename_all = "snake_case")]
pub enum ValidationErrorCode {
    /// Zone name is not a valid DNS name
    InvalidZoneName,
    /// Record name is not a valid relative DNS name
    InvalidRecordName,
    /// Record type is not supported
    UnsupportedRecordType,
    /// IPv4 address format is invalid
    InvalidIpv4Address,
    /// IPv6 address format is invalid
    InvalidIpv6Address,
    /// CNAME target is not a valid DNS name
    InvalidCnameTarget,
    /// MX record format is invalid (priority + target)
    InvalidMxRecord,
    /// NS record target is not a valid DNS name
    InvalidNsTarget,
    /// TXT record value is invalid
    InvalidTxtValue,
    /// SRV record format is invalid (priority weight port target)
    InvalidSrvRecord,
    /// CAA record format is invalid
    InvalidCaaRecord,
    /// Zone file failed named-checkzone validation
    ZoneValidationFailed,
    /// Record value contains invalid characters
    InvalidCharacters,
    /// Label too long (>63 chars) or name too long (>253 chars)
    LabelTooLong,
    /// Empty label or name
    EmptyLabel,
    /// Invalid TTL value
    InvalidTtl,
}

impl ValidationErrorCode {
    pub fn title(&self) -> &'static str {
        match self {
            Self::InvalidZoneName => "Invalid Zone Name",
            Self::InvalidRecordName => "Invalid Record Name",
            Self::UnsupportedRecordType => "Unsupported Record Type",
            Self::InvalidIpv4Address => "Invalid IPv4 Address",
            Self::InvalidIpv6Address => "Invalid IPv6 Address",
            Self::InvalidCnameTarget => "Invalid CNAME Target",
            Self::InvalidMxRecord => "Invalid MX Record",
            Self::InvalidNsTarget => "Invalid NS Target",
            Self::InvalidTxtValue => "Invalid TXT Value",
            Self::InvalidSrvRecord => "Invalid SRV Record",
            Self::InvalidCaaRecord => "Invalid CAA Record",
            Self::ZoneValidationFailed => "Zone Validation Failed",
            Self::InvalidCharacters => "Invalid Characters",
            Self::LabelTooLong => "Label Too Long",
            Self::EmptyLabel => "Empty Label",
            Self::InvalidTtl => "Invalid TTL",
        }
    }

    pub fn status_code(&self) -> u16 {
        match self {
            Self::UnsupportedRecordType => 400,
            Self::ZoneValidationFailed => 422,
            _ => 400,
        }
    }
}

/// Validation error with code and context
#[derive(Debug, Error, Clone, serde::Serialize, serde::Deserialize)]
#[error("{code:?}: {message}")]
pub struct ValidationError {
    pub code: ValidationErrorCode,
    pub message: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub field: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub value: Option<String>,
}

impl ValidationError {
    pub fn new(code: ValidationErrorCode, message: impl Into<String>) -> Self {
        Self {
            code,
            message: message.into(),
            field: None,
            value: None,
        }
    }

    pub fn with_field(mut self, field: &str) -> Self {
        self.field = Some(field.to_string());
        self
    }

    pub fn with_value(mut self, value: &str) -> Self {
        self.value = Some(value.to_string());
        self
    }

    pub fn to_problem_details(&self, instance: Option<&str>) -> ProblemDetails {
        let mut ext = std::collections::HashMap::new();
        ext.insert(
            "error_code".to_string(),
            serde_json::to_value(self.code).unwrap(),
        );
        if let Some(ref field) = self.field {
            ext.insert(
                "field".to_string(),
                serde_json::Value::String(field.clone()),
            );
        }
        if let Some(ref value) = self.value {
            ext.insert(
                "value".to_string(),
                serde_json::Value::String(value.clone()),
            );
        }

        ProblemDetails::new(self.code.status_code(), self.code.title())
            .with_detail(&self.message)
            .with_instance(instance.unwrap_or(""))
            .with_extensions(ext)
    }
}

/// Supported DNS record types
pub const SUPPORTED_RECORD_TYPES: &[&str] =
    &["A", "AAAA", "CNAME", "MX", "NS", "TXT", "SRV", "CAA"];

/// Validates a DNS name (absolute or relative)
/// Returns the normalized name (lowercase, no trailing dot for relative names)
pub fn validate_dns_name(name: &str, allow_absolute: bool) -> Result<String, ValidationError> {
    if name.is_empty() {
        return Err(ValidationError::new(
            ValidationErrorCode::EmptyLabel,
            "DNS name cannot be empty",
        ));
    }

    let name = name.trim();
    if name.is_empty() {
        return Err(ValidationError::new(
            ValidationErrorCode::EmptyLabel,
            "DNS name cannot be whitespace only",
        ));
    }

    let is_absolute = name.ends_with('.');
    if is_absolute && !allow_absolute {
        return Err(ValidationError::new(
            ValidationErrorCode::InvalidCharacters,
            "Absolute DNS names (ending with .) not allowed for record names",
        )
        .with_field("name")
        .with_value(name));
    }

    let labels: Vec<&str> = if is_absolute {
        name[..name.len() - 1].split('.').collect()
    } else {
        name.split('.').collect()
    };

    if labels.iter().any(|l| l.is_empty()) {
        return Err(ValidationError::new(
            ValidationErrorCode::EmptyLabel,
            "DNS name contains empty label",
        )
        .with_field("name")
        .with_value(name));
    }

    for label in &labels {
        if label.len() > 63 {
            return Err(ValidationError::new(
                ValidationErrorCode::LabelTooLong,
                format!("Label '{}' exceeds 63 characters", label),
            )
            .with_field("name")
            .with_value(name));
        }

        if !label.chars().all(|c| c.is_ascii_alphanumeric() || c == '-') {
            return Err(ValidationError::new(
                ValidationErrorCode::InvalidCharacters,
                format!(
                    "Label '{}' contains invalid characters (only a-z, 0-9, - allowed)",
                    label
                ),
            )
            .with_field("name")
            .with_value(name));
        }

        if label.starts_with('-') || label.ends_with('-') {
            return Err(ValidationError::new(
                ValidationErrorCode::InvalidCharacters,
                format!("Label '{}' cannot start or end with hyphen", label),
            )
            .with_field("name")
            .with_value(name));
        }
    }

    let total_len = if is_absolute {
        name.len()
    } else {
        name.len() + 1
    };
    if total_len > 253 {
        return Err(ValidationError::new(
            ValidationErrorCode::LabelTooLong,
            format!("DNS name exceeds 253 characters (got {})", total_len),
        )
        .with_field("name")
        .with_value(name));
    }

    Ok(name.to_lowercase())
}

/// Validates a zone name (must be absolute DNS name)
pub fn validate_zone_name(zone: &str) -> Result<String, ValidationError> {
    let normalized = validate_dns_name(zone, true)?;
    if !normalized.ends_with('.') {
        Ok(format!("{}.", normalized))
    } else {
        Ok(normalized)
    }
}

/// Validates a record name (relative DNS name, no trailing dot)
pub fn validate_record_name(name: &str) -> Result<String, ValidationError> {
    if name.trim() == "@" {
        return Ok("@".to_string());
    }

    validate_dns_name(name, false)
}

/// Validates an IPv4 address
pub fn validate_ipv4(addr: &str) -> Result<Ipv4Addr, ValidationError> {
    addr.parse().map_err(|_| {
        ValidationError::new(
            ValidationErrorCode::InvalidIpv4Address,
            format!("'{}' is not a valid IPv4 address", addr),
        )
        .with_field("value")
        .with_value(addr)
    })
}

/// Validates an IPv6 address
pub fn validate_ipv6(addr: &str) -> Result<Ipv6Addr, ValidationError> {
    addr.parse().map_err(|_| {
        ValidationError::new(
            ValidationErrorCode::InvalidIpv6Address,
            format!("'{}' is not a valid IPv6 address", addr),
        )
        .with_field("value")
        .with_value(addr)
    })
}

/// Validates a CNAME target (must be absolute DNS name)
pub fn validate_cname_target(target: &str) -> Result<String, ValidationError> {
    validate_dns_name(target, true)
}

/// Validates an MX record value (priority + target)
pub fn validate_mx_value(value: &str) -> Result<(u16, String), ValidationError> {
    let parts: Vec<&str> = value.split_whitespace().collect();
    if parts.len() != 2 {
        return Err(ValidationError::new(
            ValidationErrorCode::InvalidMxRecord,
            "MX record must have format: 'priority target' (e.g., '10 mail.example.com')",
        )
        .with_field("value")
        .with_value(value));
    }

    let priority = parts[0].parse::<u16>().map_err(|_| {
        ValidationError::new(
            ValidationErrorCode::InvalidMxRecord,
            format!("Invalid MX priority '{}': must be 0-65535", parts[0]),
        )
        .with_field("value")
        .with_value(value)
    })?;

    let target = validate_cname_target(parts[1])?;
    Ok((priority, target))
}

/// Validates an NS record target
pub fn validate_ns_target(target: &str) -> Result<String, ValidationError> {
    validate_dns_name(target, true)
}

/// Validates a TXT record value
pub fn validate_txt_value(value: &str) -> Result<String, ValidationError> {
    if value.len() > 255 {
        return Err(ValidationError::new(
            ValidationErrorCode::InvalidTxtValue,
            format!(
                "TXT record value exceeds 255 characters (got {})",
                value.len()
            ),
        )
        .with_field("value")
        .with_value(value));
    }
    Ok(value.to_string())
}

/// Validates an SRV record value (priority weight port target)
pub fn validate_srv_value(value: &str) -> Result<(u16, u16, u16, String), ValidationError> {
    let parts: Vec<&str> = value.split_whitespace().collect();
    if parts.len() != 4 {
        return Err(ValidationError::new(
            ValidationErrorCode::InvalidSrvRecord,
            "SRV record must have format: 'priority weight port target' (e.g., '10 5 443 server.example.com')",
        ).with_field("value").with_value(value));
    }

    let priority = parts[0].parse::<u16>().map_err(|_| {
        ValidationError::new(
            ValidationErrorCode::InvalidSrvRecord,
            format!("Invalid SRV priority '{}': must be 0-65535", parts[0]),
        )
        .with_field("value")
        .with_value(value)
    })?;

    let weight = parts[1].parse::<u16>().map_err(|_| {
        ValidationError::new(
            ValidationErrorCode::InvalidSrvRecord,
            format!("Invalid SRV weight '{}': must be 0-65535", parts[1]),
        )
        .with_field("value")
        .with_value(value)
    })?;

    let port = parts[2].parse::<u16>().map_err(|_| {
        ValidationError::new(
            ValidationErrorCode::InvalidSrvRecord,
            format!("Invalid SRV port '{}': must be 0-65535", parts[2]),
        )
        .with_field("value")
        .with_value(value)
    })?;

    let target = validate_dns_name(parts[3], true)?;
    Ok((priority, weight, port, target))
}

/// Validates a CAA record value (flags tag value)
pub fn validate_caa_value(value: &str) -> Result<(u8, String, String), ValidationError> {
    let parts: Vec<&str> = value.splitn(3, ' ').collect();
    if parts.len() != 3 {
        return Err(ValidationError::new(
            ValidationErrorCode::InvalidCaaRecord,
            "CAA record must have format: 'flags tag value' (e.g., '0 issue \"letsencrypt.org\"')",
        )
        .with_field("value")
        .with_value(value));
    }

    let flags = parts[0].parse::<u8>().map_err(|_| {
        ValidationError::new(
            ValidationErrorCode::InvalidCaaRecord,
            format!("Invalid CAA flags '{}': must be 0-255", parts[0]),
        )
        .with_field("value")
        .with_value(value)
    })?;

    let tag = parts[1].to_string();
    if tag.is_empty() {
        return Err(ValidationError::new(
            ValidationErrorCode::InvalidCaaRecord,
            "CAA tag cannot be empty",
        )
        .with_field("value")
        .with_value(value));
    }

    let value_str = parts[2].to_string();
    Ok((flags, tag, value_str))
}

/// Validates a single record
pub fn validate_record(record: &crate::Record) -> Result<(), ValidationError> {
    let record_type = record.record_type.to_uppercase();

    if !SUPPORTED_RECORD_TYPES.contains(&record_type.as_str()) {
        return Err(ValidationError::new(
            ValidationErrorCode::UnsupportedRecordType,
            format!(
                "Unsupported record type '{}'. Supported: {}",
                record_type,
                SUPPORTED_RECORD_TYPES.join(", ")
            ),
        )
        .with_field("type")
        .with_value(&record.record_type));
    }

    validate_record_name(&record.name)?;

    match record_type.as_str() {
        "A" => {
            validate_ipv4(&record.value)?;
        }
        "AAAA" => {
            validate_ipv6(&record.value)?;
        }
        "CNAME" => {
            validate_cname_target(&record.value)?;
        }
        "MX" => {
            validate_mx_value(&record.value)?;
        }
        "NS" => {
            validate_ns_target(&record.value)?;
        }
        "TXT" => {
            validate_txt_value(&record.value)?;
        }
        "SRV" => {
            validate_srv_value(&record.value)?;
        }
        "CAA" => {
            validate_caa_value(&record.value)?;
        }
        _ => unreachable!(),
    }

    Ok(())
}

/// Validates all records in a zone payload
pub fn validate_zone_payload(payload: &crate::ZonePayload) -> Result<(), Vec<ValidationError>> {
    let mut errors = Vec::new();

    for (idx, record) in payload.records.iter().enumerate() {
        if let Err(e) = validate_record(record) {
            let mut err = e.with_field(&format!("records[{}]", idx));
            if err.value.is_none() {
                err = err.with_value(&record.value);
            }
            errors.push(err);
        }
    }

    if errors.is_empty() {
        Ok(())
    } else {
        Err(errors)
    }
}

/// Runs named-checkzone on a zone file for final validation
pub fn validate_zone_file_with_named_checkzone(
    zone_name: &str,
    zone_file_path: &Path,
) -> Result<(), ValidationError> {
    let output = Command::new("named-checkzone")
        .args(["-q", zone_name, zone_file_path.to_str().unwrap_or("")])
        .output()
        .map_err(|e| {
            ValidationError::new(
                ValidationErrorCode::ZoneValidationFailed,
                format!("Failed to execute named-checkzone: {}", e),
            )
        })?;

    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        return Err(ValidationError::new(
            ValidationErrorCode::ZoneValidationFailed,
            format!("named-checkzone validation failed: {}", stderr.trim()),
        )
        .with_field("zone_file")
        .with_value(&zone_file_path.display().to_string()));
    }

    Ok(())
}

/// Generates a Problem Details response for multiple validation errors
pub fn validation_errors_to_problem_details(
    errors: &[ValidationError],
    instance: Option<&str>,
) -> ProblemDetails {
    let first = &errors[0];
    let mut ext = std::collections::HashMap::new();
    ext.insert("errors".to_string(), serde_json::to_value(errors).unwrap());
    ext.insert(
        "error_count".to_string(),
        serde_json::Value::Number(errors.len().into()),
    );

    ProblemDetails::new(first.code.status_code(), "Validation Failed")
        .with_detail(&format!("{} validation error(s)", errors.len()))
        .with_instance(instance.unwrap_or(""))
        .with_extensions(ext)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_validate_zone_name_valid() {
        assert!(validate_zone_name("example.com").is_ok());
        assert!(validate_zone_name("example.com.").is_ok());
        assert!(validate_zone_name("sub.example.com").is_ok());
        assert!(validate_zone_name("example.invalid").is_ok());
    }

    #[test]
    fn test_validate_zone_name_invalid() {
        assert!(validate_zone_name("").is_err());
        assert!(validate_zone_name("invalid..com").is_err());
        assert!(validate_zone_name("-example.com").is_err());
        assert!(validate_zone_name("example-.com").is_err());
        assert!(validate_zone_name("example..com").is_err()); // double dot = empty label
    }

    #[test]
    fn test_validate_record_name_valid() {
        assert!(validate_record_name("@").is_ok());
        assert!(validate_record_name("www").is_ok());
        assert!(validate_record_name("www.example").is_ok());
        assert!(validate_record_name("_dmarc").is_err()); // underscore not allowed in our strict mode
    }

    #[test]
    fn test_validate_ipv4() {
        assert!(validate_ipv4("192.0.2.1").is_ok());
        assert!(validate_ipv4("255.255.255.255").is_ok());
        assert!(validate_ipv4("256.0.0.1").is_err());
        assert!(validate_ipv4("192.0.2").is_err());
        assert!(validate_ipv4("invalid").is_err());
    }

    #[test]
    fn test_validate_ipv6() {
        assert!(validate_ipv6("2001:db8::1").is_ok());
        assert!(validate_ipv6("::1").is_ok());
        assert!(validate_ipv6("invalid").is_err());
    }

    #[test]
    fn test_validate_mx_value() {
        assert!(validate_mx_value("10 mail.example.com").is_ok());
        assert!(validate_mx_value("0 mail.example.com").is_ok());
        assert!(validate_mx_value("65535 mail.example.com").is_ok());
        assert!(validate_mx_value("65536 mail.example.com").is_err());
        assert!(validate_mx_value("10").is_err());
        assert!(validate_mx_value("invalid mail.example.com").is_err());
    }

    #[test]
    fn test_validate_srv_value() {
        assert!(validate_srv_value("10 5 443 server.example.com").is_ok());
        assert!(validate_srv_value("0 0 80 server.example.com").is_ok());
        assert!(validate_srv_value("10 5 443").is_err());
        assert!(validate_srv_value("invalid 5 443 server.example.com").is_err());
    }

    #[test]
    fn test_validate_caa_value() {
        assert!(validate_caa_value("0 issue \"letsencrypt.org\"").is_ok());
        assert!(validate_caa_value("128 iodef \"mailto:security@example.com\"").is_ok());
        assert!(validate_caa_value("256 issue \"letsencrypt.org\"").is_err());
        assert!(validate_caa_value("0 issue").is_err());
    }

    #[test]
    fn test_validate_record() {
        let record = crate::Record {
            record_type: "A".to_string(),
            name: "www".to_string(),
            value: "192.0.2.1".to_string(),
        };
        assert!(validate_record(&record).is_ok());

        let record = crate::Record {
            record_type: "A".to_string(),
            name: "www".to_string(),
            value: "invalid".to_string(),
        };
        assert!(validate_record(&record).is_err());
    }
}
